      "",
      "### Düşük CTR her zaman başlık sorunu mu demektir?",
      "",
      "Hayır. Bazen sorgu niyeti, rekabet yapısı veya sayfanın sunduğu açının beklentiyle uyumsuzluğu etkili olabilir.",
      "",
      "### Search Console yeni içerik fikirleri üretmek için kullanılabilir mi?",
      "",
