      "",
      "Bu yapı özellikle ürün çeşitliliği olan ama kullanıcıyı uzun e-ticaret akışına taşımadan önce ön ilgi toplamak isteyen markalar için değerlidir. Bazı işletmeler için katalog doğrudan sipariş öncesi filtre görevi görür; bazıları içinse satış temsilcisine gitmeden önce kullanıcının seçenekleri anlamasını sağlar.",
