      "",
      "## Düşük kaliteli lead sorunu neden oluşur?",
      "",
      "### Form çok kolay dolduruluyorsa",
      "",
      "Bazı kullanıcılar merak, refleks ya da yanlış beklenti ile formu gönderir. Özellikle tek tıklamaya yaklaşan akışlarda niyet filtresi zayıf kalabilir. Bu nedenle sadece form sayısına bakmak çoğu zaman yanıltıcıdır.",
      "",
      "### Teklif yeterince net anlatılmıyorsa",
      "",
      "Reklamda neyin teklif edildiği belirsizse kullanıcı formu ne için bıraktığını tam anlamayabilir. Sonrasında arandığında ya da mesaj atıldığında beklenti uyuşmazlığı yaşanır. Bu da ekip için zaman kaybı ve maliyet üretir.",
      "",
      "### Form soruları yanlış yapılandırılıyorsa",
      "",
      "Hiç ayıklama yapmayan çok kısa form ile gereğinden fazla uzun ve yorucu form arasında denge kurulmalıdır. Kullanıcının karar verme eşiğini bozmadan kalite sinyali toplayan yapı daha iyi sonuç verir.",
      "",
      "### Takip hızı düşükse",
      "",
      "Lead geldikten sonra saatlerce bekleniyorsa formun ilk sıcaklığı kaybolur. Meta lead form reklamlarında reklam optimizasyonu kadar operasyon hızı da belirleyicidir. Düşük kalite diye görülen bazı lead'ler aslında geç geri dönüldüğü için soğumuş olabilir.",
      "",
      "## Daha kaliteli lead için neler optimize edilmeli?",
      "",
      "### Reklam mesajını filtre görevi görecek şekilde yazın",
      "",
      "Herkese hitap eden çok genel vaatler hacmi artırabilir ama kaliteyi düşürebilir. Hedef kitleyi daha net işaretleyen, teklif kapsamını doğru anlatan ve gerekiyorsa fiyat ya da koşul çerçevesi veren mesajlar daha nitelikli lead toplayabilir.",
      "",
