      "",
      "Bu rehberde, reklam bütçenizi %40 azaltırken dönüşümlerinizi %60 artıracak kanıtlanmış taktikleri paylaşacağız. Quality Score optimizasyonundan Smart Bidding stratejilerine, negatif anahtar kelimelerden A/B testlerine kadar her şey.",
      "",
      "## 1. Quality Score: Maliyetinizi %50 Düşürün",
      "",
      "Quality Score 7+ olan anahtar kelimelerde maliyetler %16-50 daha düşüktür. Peki nedir bu Quality Score?",
      "",
      "**Quality Score Bileşenleri (1-10 arası):**",
      "",
      "- **Beklenen Tıklama Oranı (CTR)** - %35 ağırlık: Reklamınızın ne kadar tıklanacağı tahmini",
      "- **Reklam Alaka Düzeyi** - %35 ağırlık: Anahtar kelime ile reklam metni uyumu",
      "- **Açılış Sayfası Deneyimi** - %30 ağırlık: Hız, kullanılabilirlik, içerik kalitesi",
      "",
      "**Quality Score İyileştirme Taktikleri:**",
      "",
      "1. **Ad Group Segmentasyonu**: Her ad grupta 5-15 anahtar kelime olsun. 'Ayakkabı' ve 'bot' aynı grupta olmamalı.",
      "2. **Dinamik Anahtar Kelime Ekleme**: Başlıkta {KeyWord:Varsayılan Metin} kullanın.",
      "3. **Reklam Uzantıları**: En az 4 uzantı ekleyin (site link, callout, structured snippet, call).",
      "4. **Açılış Sayfası Hızı**: 3 saniye altında yükleme süresi hedefleyin.",
      "",
      "Gerçek Örnek: Bir KOBİ müşterimizde Quality Score'u 5'ten 8'e çıkardık. Sonuç? Tıklama başına maliyet %34 düştü, aynı bütçeyle %52 daha fazla trafik.",
      "",
      "## 2. Negatif Anahtar Kelimeler: Bütçe Koruyucunuz",
      "",
      "İşletmelerin %40'ı negatif anahtar kelime kullanmıyor. Bu, bütçenin boşa tıklamalara gitmesi demek.",
      "",
      "**Negatif Anahtar Kelime Kategorileri:**",
      "",
      "**Kategori 1: Ücretsiz Arayanlar (Düşük Niyet)**",
      "- ücretsiz, bedava, free, torrent, crack",
      "- indir, pdf, şablon, örnek",
      "",
      "**Kategori 2: İşe Yaramayan Kelimeler (Yanlış Eşleşme)**",
      "- iş ilanı, kariyer, staj",
      "- ikinci el, sahibinden, letgo",
      "- şikayet, yorum, inceleme",
      "",
      "**Kategori 3: Rakip Markalar (Stratejik)**",
      "- Rakip marka isimleri (dikkatli kullanın, marka ihlali olabilir)",
      "- Sadece bilgi amaçlı arayanları filtreleyin",
      "",
      "**Negatif Liste Yönetimi:**",
      "",
      "1. **Arama Terimleri Raporunu Haftalık İnceleyin**: Hangi kelimeler tıklama alıyor ama dönüşüm yok?",
      "2. **Paylaşılan Negatif Listeler**: Tüm kampanyalarda geçerli genel listeler oluşturun.",
      "3. **Kampanya vs Ad Group**: Kampanya düzeyinde genel, ad group düzeyinde spesifik negatifler.",
      "",
      "Vaka Çalışması: Bir e-ticaret sitesi 'ayakkabı' genel kelimesinde 'iş ilanı', 'ücretsiz', 'resim' gibi kelimeleri negatif ekledi. Sonuç? Aylık 12.000 TL boşa harcamadan tasarruf.",
      "",
      "## 3. Smart Bidding: Yapay Zeka ile ROI Artırma",
      "",
      "2026'da manuel teklif verme yerine Smart Bidding kullanmayanlar geride kalıyor. İşte stratejiler:",
      "",
      "**Hedef ROAS (Return on Ad Spend):**",
      "",
      "E-ticaret için ideal. Her 1 TL reklam harcamasından ne kadar gelir istediğinizi belirtin.",
      "- Başlangıç: Mevcut ROAS + %20",
      "- Örnek: Şu an 3:1 ROAS (3 TL gelir / 1 TL reklam) → Hedef: 3.6:1",
      "- Öğrenme süresi: 7-14 gün, sabırlı olun",
      "",
      "**Hedef CPA (Cost Per Acquisition):**",
      "",
      "Lead generation için ideal. Bir müşteri kazanma maliyeti.",
      "- Mevcut CPA'nızı analiz edin",
      "- Hedef: Mevcut - %15 (yavaş yavaş düşürün)",
      "- Minimum 30 günlük veri gerekli",
      "",
      "**Maksimize Dönüşümler:**",
      "",
      "Bütçenizi tam kullanmak ve maksimum dönüşüm istiyorsanız. ROAS hedefiniz yoksa.",
      "",
      "**Maksimize Dönüşüm Değeri:**",
      "",
      "Sepet değeri yüksek siparişleri hedefleyin. Dinamik remarketing ile birlikte kullanın.",
      "",
      "**Smart Bidding En İyi Uygulamaları:**",
      "",
      "- Sadece dönüşüm takibi yapılan kampanyalarda kullanın",
