      "- Mevsimsel dönemlerde (Bayram, Black Friday) manuel geçiş düşünün",
      "",
      "## 4. Açılış Sayfası Optimizasyonu (LP): Dönüşüm Kırıcı",
      "",
      "Reklam harcamalarının %70'i açılış sayfası optimizasyonuna bağlı. İyi bir LP = Düşük CPC + Yüksek dönüşüm.",
      "",
      "**Google Ads Uyumlu LP Kontrol Listesi:**",
      "",
      "- **Hız**: Mobil 3sn, Desktop 2sn altında (PageSpeed Insights)",
