      "- **Yukarıda Kal**: Kritik bilgiler ilk ekranda (fold üstü)",
      "- **Tek CTA**: Sayfada bir primary call-to-action (karmaşıklık yok)",
      "- **Güven Sinyalleri**: Müşteri yorumları, logolar, sertifikalar",
      "- **Mobil Uyum**: Dokunmatik butonlar, hızlı yükleme",
      "",
      "**A/B Test Öncelikleri:**",
      "",
      "1. Başlık (en yüksek etki)",
      "2. CTA butonu rengi ve metni",
      "3. Form alanı sayısı (az = iyi)",
      "4. Sosyal kanıt yerleşimi",
      "5. Fotoğraf/video kullanımı",
      "",
      "Gerçek Örnek: Bir SaaS firması için 'Ücretsiz Deneme' yerine '14 Gün Ücretsiz Kullan' CTA'sı test ettik. Dönüşüm %23 arttı.",
      "",
      "## 5. Kampanya Yapısı: Hesap Mimarisinin Önemi",
      "",
      "Karmaşık kampanya yapısı = Yönetim zorluğu = Verimsiz harcama.",
      "",
      "**İdeal Hesap Yapısı:**",
      "",
      "Hesap yapısı 4 temel bölümden oluşur:",
      "",
      "1. Marka Kampanyaları (Yüksek ROAS) - Exact Match",
      "2. Generic Kampanyalar (Hacim) - Phrase Match ile kategoriler",
      "3. Remarketing (Düşük Maliyet) - Dinamik ve standart",
      "4. Test Kampanyaları - Yeni anahtar kelimeler",
      "",
      "",
      "**Match Type Stratejisi:**",
      "",
      "- **Exact Match** (%70 bütçe): En yüksek dönüşüm, kontrollü harcama",
      "- **Phrase Match** (%25 bütçe): Yeni fırsatlar keşfi",
      "- **Broad Match** (%5 bütçe): Akıllı Bidding ile test amaçlı",
      "",
      "Not: 2024'ten sonra 'Broad Match Modifier' kaldırıldı. Phrase Match genişletilmiş anlamları kapsıyor.",
      "",
      "## 6. Reklam Metni Optimizasyonu: Tıklama Manyetizi",
      "",
      "Aynı anahtar kelime için 3-5 farklı reklam metni rotate edin. Google en iyi performans göstereni gösterir (Optimize).",
      "",
      "**ETSA Formülü (En İyi Reklam Metni):**",
      "",
      "- **E**motional Trigger: Duygusal tetikleyici (Fırsat, aciliyet, korku)",
      "- **T**angible Benefit: Somut fayda (Zamandan tasarruf, para kazanma)",
      "- **S**ocial Proof: Sosyal kanıt (10.000+ müşteri, 4.9 puan)",
      "- **A**ction: Harekete geçirici (Hemen, Bugün, Sınırlı)",
      "",
      "**Reklam Metni Şablonları:**",
      "",
      "**E-ticaret:**",
      "- Başlık: [Ürün] | %X İndirim | Ücretsiz Kargo",
      "- Açıklama: Bugüne özel fiyat. 50.000+ mutlu müşteri. 14 gün içinde iade garantisi.",
      "",
      "**B2B Hizmet:**",
      "- Başlık: [Hizmet] | 2026 Fiyatları | Ücretsiz Teklif",
      "- Açıklama: 500+ şirkete hizmet verdik. ROI garantisi. Hemen teklif alın.",
      "",
      "**Yerel İşletme:**",
      "- Başlık: [Hizmet] [Şehir] | Hemen Arayın",
      "- Açıklama: 7/24 hizmet. 15 dk'da yerinde. Ücretsiz keşif.",
      "",
      "**Responsive Search Ads (RSA) İpuçları:**",
      "",
      "- 15 başlık, 4 açıklama yazın (Google kombinasyonları test etsin)",
      "- Başlıkları 'Good' veya 'Excellent' seviyesine getirin",
      "- Sabit başlık pinleyin (marka mesajı için)",
      "- Performansı düşük başlıkları değiştirin (aylık)",
      "",
      "## 7. Performans İzleme ve Raporlama",
      "",
      "Optimize edemezseniz yönetemezsiniz. İşte takip edilmesi gereken KPI'lar:",
      "",
