      "**Category Selection**",
      "",
      "The primary category is the most important. Choose specific categories like 'Software Company', 'Digital Agency'. Gain extra visibility with secondary categories.",
      "",
      "**Business Description**",
      "",
      "Write a keyword-enriched description within the 750 character limit. Use local expressions like 'software company in Ordu', 'Altınordu web design'.",
      "",
      "**Images**",
      "",
      "Upload at least 10 photos: exterior, interior, employees, products. Adding 1-2 new photos per week keeps your profile active.",
      "",
      "## Local Keyword Strategy",
      "",
      "In local SEO, keywords are combined with city and district names:",
