      "Türkiye'de günlük 80 milyon+ e-posta gönderiliyor ve bu sayı artmaya devam ediyor. Ancak KOBİ'lerin sadece %31'i düzenli e-posta pazarlama yapıyor. Bu büyük bir fırsat - rekabet henüz doymadı.",
      "",
      "## Neden E-posta Pazarlama? (Rakamlarla)",
      "",
      "**E-posta vs Diğer Kanallar:**",
