      "- Global ortalama: %21.5",
      "- Türkiye ortalama: %18.3",
      "- En yüksek sektör: Eğitim (%25.1)",
      "",
      "## 2026 E-posta Pazarlama Trendleri",
      "",
      "### 1. Hyper-Personalization (Aşırı Kişiselleştirme)",
      "",
      "Artık sadece 'Merhaba [İsim]' yetmiyor. Gerçek kişiselleştirme: Davranışsal, coğrafi, demografik, işlemsel ve zamana dayalı.",
      "",
      "**Örnek:**",
      "Kötü: 'Merhaba Ahmet, yeni ürünlerimizi gör!'",
      "İyi: 'Ahmet, geçen hafta baktığınız laptop için özel fiyat!'",
      "",
      "### 2. AI Destekli E-posta Pazarlama",
      "",
      "Yapay Zeka Kullanım Alanları:",
      "- Konu satırı optimizasyonu",
      "- Gönderi zamanı optimizasyonu",
      "- İçerik önerisi",
      "- Otomatik segmentasyon",
      "- A/B testleri",
      "",
      "## E-posta Pazarlama Altyapısı Seçimi",
      "",
      "**Mailchimp:** Ücretsiz plan: 500 kontak, 1.000 gönderi/ay. Kullanıcı dostu arayüz.",
      "",
      "**Brevo:** Günde 300 e-posta ücretsiz. SMS entegrasyonu, Türkçe desteği.",
      "",
      "**MailerLite:** 1.000 kontak/12.000 e-posta ücretsiz. İyi fiyat/performans.",
      "",
      "**İleti Merkezi:** Türkiye merkezli, SMS + E-posta + Push, KVKK uyumlu.",
      "",
      "## E-posta Türleri ve İçerik Stratejisi",
      "",
      "### 1. Hoş Geldin Serisi (Welcome Series)",
